#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe curl-check-many-urls-from-one-config. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site site/docs broken broken/docs
printf '%s\n' 'ok' > site/health.txt
printf '%s\n' '1.4.2' > site/version.txt
printf '%s\n' 'read me' > site/docs/readme.txt
printf '%s\n' 'ok' > broken/health.txt
printf '%s\n' 'read me' > broken/docs/readme.txt
cat > urls.conf <<'EOF'
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Every URL the deployment must answer. The ports come from the command line:
#   curl --variable http_port=<port> --variable ftp_port=<port> -K urls.conf
fail
silent
show-error
fail-early
write-out = "%{onerror}FAILED %{url}\n"

expand-url = "http://127.0.0.1:{{http_port}}/health.txt"
out-null
expand-url = "http://127.0.0.1:{{http_port}}/version.txt"
out-null
expand-url = "ftp://127.0.0.1:{{ftp_port}}/docs/readme.txt"
out-null
EOF
surl -v --log-file main.log --directory site --allow-anonymous http://127.0.0.1:8080/ ftp://127.0.0.1:8081/ &
sleep 1
curl --variable http_port=8080 --variable ftp_port=8081 -K urls.conf
kill $(jobs -p)
